INSERT INTO "public"."lessons" ("id", "title", "description", "pillar_id", "difficulty", "xp_reward", "content", "image_url", "audio_url", "estimated_duration", "is_active", "sort_order", "created_at", "updated_at", "audio_assets", "visual_assets", "interactive_config", "lesson_code", "unit_number", "lesson_number", "level_name", "description_pt", "under_construction", "target_audience", "is_preview", "edition", "skill_axes") VALUES ('fd687373-ec73-4f63-aa9b-3db68fb7a037', '1. Pitch Talk: Calls of the Game', null, 102, null, 100, '{"type":"multi_step","unit":2,"steps":[{"id":"step-1","type":"scenario","title":"1. The Calls of the Game","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/scenarios/training-drill.png"},{"id":"step-2","type":"vocabulary","title":"The six essential calls","content":"Every training session starts the same way — with six short calls flying around the pitch. You''ve just signed. Learn them so you never freeze when you hear them.","vocabulary":[{"english":"Man on!","example":"You get the ball. A teammate shouts ''Man on!'' — a defender is coming.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/pitch-talk/man-on.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/man-on.png","usage_tip":"The most important call in football. Protect the ball with your body, don''t turn into pressure.","translation":"Marcado!","pronunciation":"/mæn ɒn/"},{"english":"Time!","example":"You control the ball. A teammate shouts ''Time!'' — you have space to think.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/pitch-talk/time.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/time.png","usage_tip":"The opposite of ''Man on!'' — take a breath and pick your pass.","translation":"Tempo!","pronunciation":"/taɪm/"},{"english":"Away!","example":"Under pressure in your own box. The keeper shouts ''Away!'' — clear the ball long.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/pitch-talk/away.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/away.png","usage_tip":"In your own third of the pitch, ''Away!'' means safety first. Don''t be clever.","translation":"Manda embora!","pronunciation":"/əˈweɪ/"},{"english":"Turn!","example":"You receive with your back to goal. A teammate shouts ''Turn!'' — no one is behind you.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/pitch-talk/turn.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/turn.png","usage_tip":"Trust the call. Your teammate sees what you can''t. Turn quickly and lift your head.","translation":"Pode virar!","pronunciation":"/tɜːn/"},{"english":"Play!","example":"You''ve made a small mistake. The coach shouts ''Play!'' — keep going.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/pitch-talk/play.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/play.png","usage_tip":"Reset instantly. Coaches watch how you respond to mistakes as much as what you do right.","translation":"Segue!","pronunciation":"/pleɪ/"},{"english":"Line!","example":"Playing right-back. The centre-back shouts ''Line!'' — push up together.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/pitch-talk/line.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/line.png","usage_tip":"You''ll hear this from centre-backs when they want the whole defence to step up and catch strikers offside.","translation":"Linha!","pronunciation":"/laɪn/"}]},{"id":"step-3","type":"drag_drop_vocab","title":"Match the call to what it means","content":"Drag each call onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"man-on-c","english":"Man on!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/pitch-talk/man-on.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/man-on.png","translation":"Marcado!"},{"id":"time-c","english":"Time!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/pitch-talk/time.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/time.png","translation":"Tempo!"},{"id":"away-c","english":"Away!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/pitch-talk/away.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/away.png","translation":"Manda embora!"},{"id":"turn-c","english":"Turn!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/pitch-talk/turn.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/turn.png","translation":"Pode virar!"},{"id":"play-c","english":"Play!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/pitch-talk/play.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/play.png","translation":"Segue!"},{"id":"line-c","english":"Line!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/pitch-talk/line.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/line.png","translation":"Linha!"}],"display_mode":"image"}},{"id":"step-4","type":"ai_speech_practice","title":"Shout them out","prompt":"","context":"The six essential pitch calls","xp_reward":20,"expectedText":"Man on! Time! Away! Turn! Play! Line!","instructions":{"en":"Sharp, loud, no hesitation. On a real pitch, a whisper is worse than silence.","pt":"Nítido, alto, sem hesitação. Num campo de verdade, um sussurro é pior que o silêncio."}},{"id":"step-5","type":"vocabulary","title":"Four calls that build the team","content":"The best teammates don''t just call warnings — they lift the group. Four short phrases that make you the player everyone wants next to them.","vocabulary":[{"english":"Well done!","example":"Your teammate makes a great tackle. ''Well done, mate!''","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/pitch-talk/well-done.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/well-done.png","usage_tip":"Two syllables, big effect. Say it after every good moment — even in training.","translation":"Muito bem!","pronunciation":"/wel dʌn/"},{"english":"Keep going!","example":"A teammate misses a chance. ''Keep going — next one!''","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/pitch-talk/keep-going.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/keep-going.png","usage_tip":"When a teammate has just messed up. Lifts heads. Coaches love hearing it from teammates.","translation":"Continua!","pronunciation":"/kiːp ˈɡəʊɪŋ/"},{"english":"Good ball!","example":"Your teammate plays a perfect pass. ''Good ball!''","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/pitch-talk/good-ball.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/good-ball.png","usage_tip":"Acknowledges a great pass. Small compliment, big team effect over 90 minutes.","translation":"Boa bola!","pronunciation":"/ɡʊd bɔːl/"},{"english":"Unlucky!","example":"A teammate hits the post. ''Unlucky, mate!''","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/pitch-talk/unlucky.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/unlucky.png","usage_tip":"British football classic. Used when the player did the right thing but the result was unlucky. Very English.","translation":"Azar!","pronunciation":"/ʌnˈlʌki/"}]},{"id":"step-6","type":"drag_drop_vocab","title":"Match the encouragement call","content":"Drag each phrase onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"e-well-done","english":"Well done!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/pitch-talk/well-done.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/well-done.png","translation":"Muito bem!"},{"id":"e-keep","english":"Keep going!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/pitch-talk/keep-going.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/keep-going.png","translation":"Continua!"},{"id":"e-good","english":"Good ball!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/pitch-talk/good-ball.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/good-ball.png","translation":"Boa bola!"},{"id":"e-unlucky","english":"Unlucky!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/pitch-talk/unlucky.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/unlucky.png","translation":"Azar!"}],"display_mode":"image"}},{"id":"step-7","type":"audio_comprehension","title":"Listen to a real drill","content":"A five-a-side training drill. Nine calls in thirty seconds. How many can you catch?","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/scenarios/training-drill.png","questions":[{"id":"q1","text":"What is the first call you hear after ''Man on!''?","type":"multiple_choice","options":["Turn!","Play!","Away!","Line!"],"correct_answer":"Turn!"},{"id":"q2","text":"After ''Cross!'' — what does the teammate shout?","type":"multiple_choice","options":["Well done, mate","Keep going","Good ball","Unlucky"],"correct_answer":"Well done, mate"},{"id":"q3","text":"''Yellows, get up there and ___!''","type":"gap_fill","options":["press","line","turn","play"],"correct_answer":"press"}],"audio_config":{"audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/pitch-talk/comprehension-5-a-side-drill.m4a","transcript":"Right team, kick off. Diego, on the ball. Man on! Turn — you''ve got time! Play it wide. Cross! Well done, mate. Reds, drop back — mark up. Yellows, get up there and press. Line! Push up! Good ball. Keep going. Play on!","duration_seconds":28,"transcript_reveal":"after_first_attempt","max_replays_for_full_xp":3},"translation_available":false},{"id":"step-8","type":"ai_gap_fill","title":"Choose your call","content":"Fill in the gap.","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/scenarios/training-drill.png","sentences":[{"id":"gap-1","text":"Your teammate has just made a great tackle. You shout: ''___ done!''","context":"Praising a teammate","options":["Well","Good","Keep","Big"],"hint_context":"Two words: [word] done!","correct_answers":["Well"]},{"id":"gap-2","text":"A defender is closing in fast on your teammate. You shout: ''___ on!''","context":"Warning a teammate","options":["Man","Turn","Time","Play"],"hint_context":"The most important warning call in football.","correct_answers":["Man"]}],"xp_reward":25},{"id":"step-9","type":"memory_match","title":"Pitch calls review","xp_reward":60,"vocabulary":[{"en":"Man on!","id":1,"pt":"Marcado!","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/man-on.png"},{"en":"Time!","id":2,"pt":"Tempo!","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/time.png"},{"en":"Turn!","id":3,"pt":"Pode virar!","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/turn.png"},{"en":"Play!","id":4,"pt":"Segue!","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/play.png"},{"en":"Well done!","id":5,"pt":"Muito bem!","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/well-done.png"},{"en":"Keep going!","id":6,"pt":"Continua!","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/keep-going.png"},{"en":"Good ball!","id":7,"pt":"Boa bola!","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/good-ball.png"},{"en":"Unlucky!","id":8,"pt":"Azar!","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/pitch-talk/unlucky.png"}],"display_mode":"image"},{"id":"step-10","type":"completion","title":"Voice on the Pitch","content":"You''ve got the six calls that keep you alive on a training pitch, and four calls that make you the teammate everyone wants alongside them. Coaches notice the quiet ones. They notice the loud ones more. Next session: what the coach is drawing on that whiteboard.","xp_reward":120,"achievements":["✅ Six warning calls learned","✅ Four encouragement calls mastered","✅ First real drill decoded by ear"],"badge_unlocked":"Voice on the Pitch","next_lesson_preview":"Next: Session 2.2 — Your Role in the Shape.","translation_available":true}],"session":1,"difficulty":"A2","skill_area":"pitch-talk"}', null, null, null, true, 7, '2026-08-14 01:22:24.7059+00', '2026-08-14 01:22:24.7059+00', null, null, null, null, 2, 1, null, null, null, 'players', false, 'propath_26_27', ARRAY['pitch_talk']), ('3612eb77-a4c0-44b8-a099-ba860d5f2584', '2. Tactics: Your Role', null, 102, null, 100, '{"type":"multi_step","unit":2,"steps":[{"id":"step-1","type":"scenario","title":"2. Your Role in the Shape","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/scenarios/whiteboard-detail.png"},{"id":"step-2","type":"vocabulary","title":"How you move — six modern instructions","content":"You know the shape. Now the coach tells you how to move inside it. Six instructions you''ll hear in every modern professional dressing room.","vocabulary":[{"english":"press","example":"When they have the ball — press!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/tactics/press.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/press.png","usage_tip":"Put immediate pressure on the ball-carrier. Fast, aggressive, coordinated. The defining word of modern football.","translation":"pressionar","pronunciation":"/pres/"},{"english":"drop back","example":"They''re breaking — drop back!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/drop-back.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/drop-back.png","usage_tip":"Move quickly towards your own goal to defend. The opposite of pressing.","translation":"recuar","pronunciation":"/drɒp bæk/"},{"english":"push up","example":"We''ve won the ball — push up!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/push-up.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/push-up.png","usage_tip":"Move as a team towards the opponent''s goal. Compress the space they have.","translation":"subir a marcação","pronunciation":"/pʊʃ ʌp/"},{"english":"stay wide","example":"Wingers, stay wide — stretch them!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/stay-wide.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/stay-wide.png","usage_tip":"Don''t drift into the middle. Keep the pitch big. A winger''s cardinal rule until they''re told otherwise.","translation":"fica aberto","pronunciation":"/steɪ waɪd/"},{"english":"cut inside","example":"Cut inside and shoot!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/cut-inside.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/cut-inside.png","usage_tip":"Move from the wing towards the centre. The signature move of an inverted winger. Think Salah, think Vinícius.","translation":"entra por dentro","pronunciation":"/kʌt ɪnˈsaɪd/"},{"english":"overlap","example":"Full-back, overlap!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/overlap.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/overlap.png","usage_tip":"Run around the outside of your winger — behind or beyond them — to create a two-on-one.","translation":"sobreposição","pronunciation":"/ˌəʊvəˈlæp/"}]},{"id":"step-3","type":"drag_drop_vocab","title":"Match the instruction","content":"Drag each instruction onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"t-press","english":"Press","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/tactics/press.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/press.png","translation":"Pressionar"},{"id":"t-drop","english":"Drop back","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/drop-back.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/drop-back.png","translation":"Recuar"},{"id":"t-push","english":"Push up","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/push-up.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/push-up.png","translation":"Subir a marcação"},{"id":"t-wide","english":"Stay wide","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/stay-wide.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/stay-wide.png","translation":"Fica aberto"},{"id":"t-inside","english":"Cut inside","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/cut-inside.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/cut-inside.png","translation":"Entra por dentro"},{"id":"t-overlap","english":"Overlap","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/overlap.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/overlap.png","translation":"Sobreposição"}],"display_mode":"image"}},{"id":"step-4","type":"ai_speech_practice","title":"Practise the instructions","prompt":"","context":"Modern tactical instructions","xp_reward":20,"expectedText":"Press. Drop back. Push up. Stay wide. Cut inside. Overlap.","instructions":{"en":"","pt":""}},{"id":"step-5","type":"vocabulary","title":"Reading the shape","content":"Four words describe how the whole team looks from above. When a coach uses them, they''re describing the whole picture, not just you.","vocabulary":[{"english":"high line","example":"We play a high line — press them everywhere.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/high-line.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/high-line.png","usage_tip":"The defensive line pushed up close to the halfway line. Squeezes the pitch. Risks balls in behind.","translation":"linha alta","pronunciation":"/haɪ laɪn/"},{"english":"low block","example":"Sit in a low block — protect the box.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/low-block.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/low-block.png","usage_tip":"The whole team defends deep, close to the goal. Frustrates the attackers. Wins games on the counter.","translation":"bloco baixo","pronunciation":"/ləʊ blɒk/"},{"english":"compact","example":"Stay compact — no gaps.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/compact.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/compact.png","usage_tip":"Small distances between all your players. Nobody isolated, nobody strayed. The base of good defending.","translation":"compacto","pronunciation":"/ˈkɒmpækt/"},{"english":"in the pocket","example":"Find him in the pocket between the lines.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/in-the-pocket.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/in-the-pocket.png","usage_tip":"The space between the opposition midfield and defence. The playmaker''s home. Where a number 10 lives.","translation":"entre linhas","pronunciation":"/ɪn ðə ˈpɒkɪt/"}]},{"id":"step-6","type":"drag_drop_vocab","title":"Match the shape word","content":"Drag each word onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"s-high","english":"High line","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/high-line.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/high-line.png","translation":"Linha alta"},{"id":"s-low","english":"Low block","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/low-block.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/low-block.png","translation":"Bloco baixo"},{"id":"s-compact","english":"Compact","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/compact.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/compact.png","translation":"Compacto"},{"id":"s-pocket","english":"In the pocket","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/in-the-pocket.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/in-the-pocket.png","translation":"Entre linhas"}],"display_mode":"image"}},{"id":"step-7","type":"ai_gap_fill","title":"The coach''s instructions","content":"Fill in the gap.","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/scenarios/whiteboard-detail.png","sentences":[{"id":"gap-1","text":"''They''ve won it — everyone ___ back!''","context":"Losing possession — defensive command","options":["drop","push","stay","cut"],"hint_context":"Move quickly towards your own goal.","correct_answers":["drop"]},{"id":"gap-2","text":"''When we press, we squeeze them — stay ___!''","context":"Team shape while pressing","options":["compact","wide","high","low"],"hint_context":"Small distances between players — no gaps.","correct_answers":["compact"]}],"xp_reward":25},{"id":"step-8","type":"memory_match","title":"Tactical review","xp_reward":60,"vocabulary":[{"en":"Press","id":1,"pt":"Pressionar","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/press.png"},{"en":"Drop back","id":2,"pt":"Recuar","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/drop-back.png"},{"en":"Stay wide","id":3,"pt":"Fica aberto","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/stay-wide.png"},{"en":"Cut inside","id":4,"pt":"Entra por dentro","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/cut-inside.png"},{"en":"Overlap","id":5,"pt":"Sobreposição","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/overlap.png"},{"en":"High line","id":6,"pt":"Linha alta","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/high-line.png"},{"en":"Low block","id":7,"pt":"Bloco baixo","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/low-block.png"},{"en":"In the pocket","id":8,"pt":"Entre linhas","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/in-the-pocket.png"}],"display_mode":"image"},{"id":"step-9","type":"completion","title":"System Ready","content":"You''ve got the six movements a modern coach asks for, plus the four words that describe the whole team''s shape. When the whiteboard comes out, you don''t just understand where you play — you understand HOW you play. Next session: the coach sits you down for your first proper review.","xp_reward":120,"achievements":["✅ Six modern tactical instructions","✅ Four shape-reading terms","✅ Coach''s whiteboard understood"],"badge_unlocked":"System Ready","next_lesson_preview":"Next: Session 2.3 — Your First Review.","translation_available":true}],"session":2,"difficulty":"A2","skill_area":"tactics"}', null, null, null, true, 8, '2026-08-14 01:29:13.027653+00', '2026-08-14 01:29:13.027653+00', null, null, null, null, 2, 2, null, null, null, 'players', false, 'propath_26_27', ARRAY['tactics']), ('fc915539-2f3f-4cfa-a1f9-072010e89137', '3. Coach: First Review', null, 102, null, 100, '{"type":"multi_step","unit":2,"steps":[{"id":"step-1","type":"scenario","title":"2. Your Role in the Shape","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/scenarios/whiteboard-detail.png"},{"id":"step-2","type":"vocabulary","title":"How you move — six modern instructions","content":"You know the shape. Now the coach tells you how to move inside it. Six instructions you''ll hear in every modern professional dressing room.","vocabulary":[{"english":"press","example":"When they have the ball — press!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/tactics/press.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/press.png","usage_tip":"Put immediate pressure on the ball-carrier. Fast, aggressive, coordinated. The defining word of modern football.","translation":"pressionar","pronunciation":"/pres/"},{"english":"drop back","example":"They''re breaking — drop back!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/drop-back.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/drop-back.png","usage_tip":"Move quickly towards your own goal to defend. The opposite of pressing.","translation":"recuar","pronunciation":"/drɒp bæk/"},{"english":"push up","example":"We''ve won the ball — push up!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/push-up.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/push-up.png","usage_tip":"Move as a team towards the opponent''s goal. Compress the space they have.","translation":"subir a marcação","pronunciation":"/pʊʃ ʌp/"},{"english":"stay wide","example":"Wingers, stay wide — stretch them!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/stay-wide.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/stay-wide.png","usage_tip":"Don''t drift into the middle. Keep the pitch big. A winger''s cardinal rule until they''re told otherwise.","translation":"fica aberto","pronunciation":"/steɪ waɪd/"},{"english":"cut inside","example":"Cut inside and shoot!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/cut-inside.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/cut-inside.png","usage_tip":"Move from the wing towards the centre. The signature move of an inverted winger. Think Salah, think Vinícius.","translation":"entra por dentro","pronunciation":"/kʌt ɪnˈsaɪd/"},{"english":"overlap","example":"Full-back, overlap!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/overlap.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/overlap.png","usage_tip":"Run around the outside of your winger — behind or beyond them — to create a two-on-one.","translation":"sobreposição","pronunciation":"/ˌəʊvəˈlæp/"}]},{"id":"step-3","type":"drag_drop_vocab","title":"Match the instruction","content":"Drag each instruction onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"t-press","english":"Press","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/tactics/press.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/press.png","translation":"Pressionar"},{"id":"t-drop","english":"Drop back","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/drop-back.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/drop-back.png","translation":"Recuar"},{"id":"t-push","english":"Push up","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/push-up.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/push-up.png","translation":"Subir a marcação"},{"id":"t-wide","english":"Stay wide","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/stay-wide.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/stay-wide.png","translation":"Fica aberto"},{"id":"t-inside","english":"Cut inside","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/cut-inside.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/cut-inside.png","translation":"Entra por dentro"},{"id":"t-overlap","english":"Overlap","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/overlap.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/overlap.png","translation":"Sobreposição"}],"display_mode":"image"}},{"id":"step-4","type":"ai_speech_practice","title":"Practise the instructions","prompt":"","context":"Modern tactical instructions","xp_reward":20,"expectedText":"Press. Drop back. Push up. Stay wide. Cut inside. Overlap.","instructions":{"en":"","pt":""}},{"id":"step-5","type":"vocabulary","title":"Reading the shape","content":"Four words describe how the whole team looks from above. When a coach uses them, they''re describing the whole picture, not just you.","vocabulary":[{"english":"high line","example":"We play a high line — press them everywhere.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/tactics/high-line.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supaba