d":2,"pt":"Recuar","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/drop-back.png"},{"en":"Stay wide","id":3,"pt":"Fica aberto","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/stay-wide.png"},{"en":"Cut inside","id":4,"pt":"Entra por dentro","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/cut-inside.png"},{"en":"Overlap","id":5,"pt":"Sobreposição","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/overlap.png"},{"en":"High line","id":6,"pt":"Linha alta","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/high-line.png"},{"en":"Low block","id":7,"pt":"Bloco baixo","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/low-block.png"},{"en":"In the pocket","id":8,"pt":"Entre linhas","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/tactics/in-the-pocket.png"}],"display_mode":"image"},{"id":"step-9","type":"completion","title":"System Ready","content":"You''ve got the six movements a modern coach asks for, plus the four words that describe the whole team''s shape. When the whiteboard comes out, you don''t just understand where you play — you understand HOW you play. Next session: the coach sits you down for your first proper review.","xp_reward":120,"achievements":["✅ Six modern tactical instructions","✅ Four shape-reading terms","✅ Coach''s whiteboard understood"],"badge_unlocked":"System Ready","next_lesson_preview":"Next: Session 2.3 — Your First Review.","translation_available":true}],"session":2,"difficulty":"A2","skill_area":"tactics"}', null, null, null, true, 9, '2026-08-14 01:30:46.140338+00', '2026-08-14 01:30:46.140338+00', null, null, null, null, 2, 3, null, null, null, 'players', false, 'propath_26_27', ARRAY['coach']), ('22ce512c-0188-437a-8911-bb093d8bc770', '4. Media: First Interview', null, 102, null, 100, '{"type":"multi_step","unit":2,"steps":[{"id":"step-1","type":"scenario","title":"4. Your First Interview","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/scenarios/press-conference.png"},{"id":"step-2","type":"vocabulary","title":"The introduction phrases","content":"Your first ever interview. Camera, microphone, a reporter you''ve never met. Four phrases every professional footballer opens with. Learn them — even Messi uses them.","vocabulary":[{"english":"I''m very happy to be here.","example":"''First of all, I''m very happy to be here.''","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/media/happy-to-be-here.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/happy-to-be-here.png","usage_tip":"The universal opener. Says: ''I know I''m lucky, I''m grateful.'' Fans and clubs love it.","translation":"Estou muito feliz de estar aqui.","pronunciation":"/aɪm ˈveri ˈhæpi tə biː hɪə/"},{"english":"It''s a dream come true.","example":"''Playing for this club is a dream come true.''","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/media/dream-come-true.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/dream-come-true.png","usage_tip":"The signing-day phrase. Emotional, personal, safe. Every fan wants to hear it about their club.","translation":"É um sonho realizado.","pronunciation":"/ɪts ə driːm kʌm truː/"},{"english":"Thank you for the question.","example":"''Thank you for the question. It''s a good one.''","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/media/thank-you-for-the-question.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/thank-you-for-the-question.png","usage_tip":"Buys you three seconds to think of an answer. Sounds respectful. Journalists never mind.","translation":"Obrigado pela pergunta.","pronunciation":"/θæŋk juː fə ðə ˈkwestʃən/"},{"english":"I want to help the team.","example":"''My goal is simple — I want to help the team.''","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/media/help-the-team.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/help-the-team.png","usage_tip":"The team-first phrase. Says: ''I''m not selfish, I''m here for us.'' Coaches read every interview.","translation":"Quero ajudar o time.","pronunciation":"/aɪ wɒnt tə help ðə tiːm/"}]},{"id":"step-3","type":"drag_drop_vocab","title":"Match the interview opener","content":"Drag each phrase onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"m-happy","english":"I''m very happy to be here.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/media/happy-to-be-here.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/happy-to-be-here.png","translation":"Estou muito feliz de estar aqui."},{"id":"m-dream","english":"It''s a dream come true.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/media/dream-come-true.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/dream-come-true.png","translation":"É um sonho realizado."},{"id":"m-thank","english":"Thank you for the question.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/media/thank-you-for-the-question.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/thank-you-for-the-question.png","translation":"Obrigado pela pergunta."},{"id":"m-help","english":"I want to help the team.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/media/help-the-team.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/help-the-team.png","translation":"Quero ajudar o time."}],"display_mode":"image"}},{"id":"step-4","type":"vocabulary","title":"The safe answers","content":"When the reporter asks a hard question, these are the phrases that never backfire. Every top player uses them. Every day.","vocabulary":[{"english":"We take it game by game.","example":"''We''re not thinking about the trophy — we take it game by game.''","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/media/game-by-game.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/game-by-game.png","usage_tip":"The classic ''don''t look too far ahead'' answer. Says nothing risky. Coaches teach this on day one.","translation":"Vamos jogo a jogo.","pronunciation":"/wiː teɪk ɪt ɡeɪm baɪ ɡeɪm/"},{"english":"We work as a team.","example":"''The goals aren''t just mine — we work as a team.''","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/media/work-as-a-team.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/work-as-a-team.png","usage_tip":"Deflects individual praise onto the group. Perfect for after a match-winning performance.","translation":"Trabalhamos como equipe.","pronunciation":"/wiː wɜːk əz ə tiːm/"},{"english":"The manager has been great.","example":"''I''m settling in well — the manager has been great with me.''","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/media/manager-been-great.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/manager-been-great.png","usage_tip":"Always praise the manager in public. Behind closed doors is different, but a microphone is always public.","translation":"O treinador tem sido ótimo.","pronunciation":"/ðə ˈmænɪdʒə həz biːn ɡreɪt/"},{"english":"The fans have been amazing.","example":"''The support has been unbelievable — the fans have been amazing.''","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/media/fans-amazing.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/fans-amazing.png","usage_tip":"Praise the fans. They read every interview. It costs you nothing and buys you their loyalty.","translation":"A torcida tem sido incrível.","pronunciation":"/ðə fænz həv biːn əˈmeɪzɪŋ/"}]},{"id":"step-5","type":"drag_drop_vocab","title":"Match the safe answer","content":"Drag each phrase onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"s-game","english":"We take it game by game.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/media/game-by-game.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/game-by-game.png","translation":"Vamos jogo a jogo."},{"id":"s-team","english":"We work as a team.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/media/work-as-a-team.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/work-as-a-team.png","translation":"Trabalhamos como equipe."},{"id":"s-mgr","english":"The manager has been great.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/media/manager-been-great.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/manager-been-great.png","translation":"O treinador tem sido ótimo."},{"id":"s-fans","english":"The fans have been amazing.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/media/fans-amazing.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/fans-amazing.png","translation":"A torcida tem sido incrível."}],"display_mode":"image"}},{"id":"step-6","type":"ai_gap_fill","title":"Handle the question","content":"Fill in the gap.","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/scenarios/press-conference.png","sentences":[{"id":"gap-1","text":"REPORTER: ''Are you going to win the title?'' YOU: ''We take it ___ by game.''","context":"Deflecting big questions","options":["game","match","step","day"],"hint_context":"The classic phrase — same word twice.","correct_answers":["game"]},{"id":"gap-2","text":"REPORTER: ''You scored three today!'' YOU: ''The goals weren''t just mine — we ___ as a team.''","context":"Deflecting individual praise","options":["work","play","run","fight"],"hint_context":"The verb that goes with ''as a team''.","correct_answers":["work"]}],"xp_reward":25},{"id":"step-7","type":"ai_speech_practice","title":"Give a full interview answer","prompt":"","context":"The reporter asks how you''re settling in","xp_reward":30,"expectedText":"Thank you for the question. I''m very happy to be here. It''s a dream come true. The manager has been great, the fans have been amazing, and I just want to help the team.","instructions":{"en":"Slow, warm, calm. Look up when you speak (in a real interview, at the camera). Don''t rush.","pt":"Devagar, caloroso, calmo. Olhe para cima quando falar (em uma entrevista de verdade, para a câmera). Não corra."}},{"id":"step-8","type":"memory_match","title":"Interview phrases review","xp_reward":60,"vocabulary":[{"en":"I''m very happy to be here.","id":1,"pt":"Estou muito feliz.","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/happy-to-be-here.png"},{"en":"It''s a dream come true.","id":2,"pt":"É um sonho realizado.","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/dream-come-true.png"},{"en":"Thank you for the question.","id":3,"pt":"Obrigado pela pergunta.","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/thank-you-for-the-question.png"},{"en":"I want to help the team.","id":4,"pt":"Quero ajudar o time.","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/help-the-team.png"},{"en":"We take it game by game.","id":5,"pt":"Vamos jogo a jogo.","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/game-by-game.png"},{"en":"We work as a team.","id":6,"pt":"Trabalhamos como equipe.","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/work-as-a-team.png"},{"en":"The manager has been great.","id":7,"pt":"O treinador tem sido ótimo.","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/manager-been-great.png"},{"en":"The fans have been amazing.","id":8,"pt":"A torcida tem sido incrível.","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/media/fans-amazing.png"}],"display_mode":"image"},{"id":"step-9","type":"completion","title":"Press-Ready","content":"You''ve got the eight phrases every professional footballer relies on in their first hundred interviews. They''re not fancy. They''re not clever. But they never get anyone in trouble — and they buy you the time to learn the rest. The Cristiano Ronaldos of the world still use these.","xp_reward":120,"achievements":["✅ Four interview opening phrases","✅ Four safe answers for hard questions","✅ First full interview response constructed"],"badge_unlocked":"Press-Ready","next_lesson_preview":"Next: Session 2.5 — The Training Week.","translation_available":true}],"session":4,"difficulty":"A2","skill_area":"media"}', null, null, null, true, 10, '2026-08-14 01:31:55.134409+00', '2026-08-14 01:31:55.134409+00', null, null, null, null, 2, 4, null, null, null, 'players', false, 'propath_26_27', ARRAY['media']), ('6c683540-ef02-4520-a9d2-bddfd790ab27', '5. Fitness: Training Week', null, 102, null, 100, '{"type":"multi_step","unit":2,"steps":[{"id":"step-1","type":"scenario","title":"5. The Training Week","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/scenarios/training-schedule.png"},{"id":"step-2","type":"vocabulary","title":"Types of training","content":"Every professional football club runs the same five kinds of session. Five words — and you can read your weekly schedule without asking anyone what to bring.","vocabulary":[{"english":"fitness training","example":"Monday morning is always fitness training.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/fitness/fitness-training.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/fitness-training.png","usage_tip":"Pure running, cardio, endurance. No ball. The one nobody enjoys but everyone needs.","translation":"treino físico","pronunciation":"/ˈfɪtnəs ˈtreɪnɪŋ/"},{"english":"technical training","example":"Technical training with the ball this afternoon.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/fitness/technical-training.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/technical-training.png","usage_tip":"Ball work — passing drills, first touch, shooting practice. The fun one.","translation":"treino técnico","pronunciation":"/ˈteknɪkəl ˈtreɪnɪŋ/"},{"english":"tactical training","example":"Tactical training — we''re working on the press.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/fitness/tactical-training.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/tactical-training.png","usage_tip":"Team shape, positioning, moves. Where the coach''s whiteboard becomes reality on the pitch.","translation":"treino tático","pronunciation":"/ˈtæktɪkəl ˈtreɪnɪŋ/"},{"english":"gym work","example":"Gym work at 8 a.m. — strength and core.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/fitness/gym-work.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/gym-work.png","usage_tip":"Weights, core, injury prevention. Modern football players spend nearly as much time here as on grass.","translation":"musculação","pronunciation":"/dʒɪm wɜːk/"},{"english":"recovery day","example":"Sunday is a recovery day — pool and stretching.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/fitness/recovery-day.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/recovery-day.png","usage_tip":"The day off training but on your body''s rehab. Ice baths, pool, massage, sleep. Career-extending.","translation":"dia de recuperação","pronunciation":"/rɪˈkʌvəri deɪ/"}]},{"id":"step-3","type":"drag_drop_vocab","title":"Match the training type","content":"Drag each session onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"tt-fit","english":"Fitness training","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/fitness/fitness-training.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/fitness-training.png","translation":"Treino físico"},{"id":"tt-tech","english":"Technical training","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/fitness/technical-training.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/technical-training.png","translation":"Treino técnico"},{"id":"tt-tac","english":"Tactical training","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/fitness/tactical-training.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/tactical-training.png","translation":"Treino tático"},{"id":"tt-gym","english":"Gym work","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/fitness/gym-work.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/gym-work.png","translation":"Musculação"},{"id":"tt-rec","english":"Recovery day","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/fitness/recovery-day.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/recovery-day.png","translation":"Dia de recuperação"}],"display_mode":"image"}},{"id":"step-4","type":"vocabulary","title":"The seven days","content":"Every day of the week — with a footballer''s version of what happens. Learn them all in one go; you''ll say them a hundred times a month.","vocabulary":[{"english":"Monday","example":"Monday: fitness training.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/fitness/monday.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/monday.png","usage_tip":"The recovery-from-Sunday day. Often lighter.","translation":"Segunda-feira","pronunciation":"/ˈmʌndeɪ/"},{"english":"Tuesday","example":"Tuesday: tactical.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/fitness/tuesday.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/tuesday.png","usage_tip":"Usually the hardest training day of the week.","translation":"Terça-feira","pronunciation":"/ˈtjuːzdeɪ/"},{"english":"Wednesday","example":"Wednesday: technical.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/fitness/wednesday.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/wednesday.png","usage_tip":"Often ball-work day.","translation":"Quarta-feira","pronunciation":"/ˈwenzdeɪ/"},{"english":"Thursday","example":"Thursday: tactical.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/fitness/thursday.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/thursday.png","usage_tip":"Preparation for the weekend match.","translation":"Quinta-feira","pronunciation":"/ˈθɜːzdeɪ/"},{"english":"Friday","example":"Friday: light session.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/fitness/friday.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/friday.png","usage_tip":"Sharpener — short, light, focused on set-pieces.","translation":"Sexta-feira","pronunciation":"/ˈfraɪdeɪ/"},{"english":"Saturday","example":"Saturday: match day.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/fitness/saturday.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/saturday.png","usage_tip":"The classic English match day — 3pm kick-off in tradition.","translation":"Sábado","pronunciation":"/ˈsætədeɪ/"},{"english":"Sunday","example":"Sunday: recovery.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/fitness/sunday.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/sunday.png","usage_tip":"Pool, massage, sleep. If no match, family day.","translation":"Domingo","pronunciation":"/ˈsʌndeɪ/"}]},{"id":"step-5","type":"ai_speech_practice","title":"Say the week","prompt":"","context":"Days of the week","xp_reward":20,"expectedText":"Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday.","instructions":{"en":"Slow and clear. Note that Wednesday is tricky — it''s said ''WENZ-day'', not ''WED-nes-day''.","pt":"Devagar e claro. Note que ''Wednesday'' é meio complicado — pronuncia-se ''UENZ-dei'', não ''UED-nes-dei''."}},{"id":"step-6","type":"vocabulary","title":"Times of the day","content":"Every training schedule uses these three words. Never trip up over ''is it before or after lunch?'' again.","vocabulary":[{"english":"in the morning","example":"Gym work in the morning.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/fitness/in-the-morning.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/in-the-morning.png","usage_tip":"Before lunch. Usually 8am to 12noon in football-world.","translation":"de manhã","pronunciation":"/ɪn ðə ˈmɔːnɪŋ/"},{"english":"in the afternoon","example":"Tactical session in the afternoon.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/fitness/in-the-afternoon.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/in-the-afternoon.png","usage_tip":"After lunch. Usually 2pm to 5pm.","translation":"de tarde","pronunciation":"/ɪn ðə ˌɑːftəˈnuːn/"},{"english":"in the evening","example":"Match in the evening.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/fitness/in-the-evening.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/in-the-evening.png","usage_tip":"After 6pm. Most weekday matches kick off here — 7:30pm or 8pm.","translation":"de noite","pronunciation":"/ɪn ðə ˈiːvnɪŋ/"}]},{"id":"step-7","type":"ai_gap_fill","title":"Read the schedule","content":"Fill in the gap.","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/scenarios/training-schedule.png","sentences":[{"id":"gap-1","text":"''Gym work at 8 a.m. — that''s in the ___.''","context":"The time of day","options":["morning","afternoon","evening","night"],"hint_context":"Before lunch.","correct_answers":["morning"]},{"id":"gap-2","text":"''On ___ we play — kick-off at 3 p.m.''","context":"The classic English match day","options":["Saturday","Monday","Wednesday","Friday"],"hint_context":"The day between Friday and Sunday.","correct_answers":["Saturday"]}],"xp_reward":25},{"id":"step-8","type":"memory_match","title":"Training week review","xp_reward":60,"vocabulary":[{"en":"Fitness training","id":1,"pt":"Treino físico","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/fitness-training.png"},{"en":"Technical training","id":2,"pt":"Treino técnico","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/technical-training.png"},{"en":"Tactical training","id":3,"pt":"Treino tático","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/tactical-training.png"},{"en":"Recovery day","id":4,"pt":"Dia de recuperação","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/recovery-day.png"},{"en":"Monday","id":5,"pt":"Segunda-feira","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/monday.png"},{"en":"Saturday","id":6,"pt":"Sábado","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/saturday.png"},{"en":"In the morning","id":7,"pt":"De manhã","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/in-the-morning.png"},{"en":"In the afternoon","id":8,"pt":"De tarde","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/fitness/in-the-afternoon.png"}],"display_mode":"image"},{"id":"step-9","type":"completion","title":"Week Reader","content":"You can read a training schedule in English — five types of session, seven days of the week, three times of day. That''s not just useful — it''s how you show up on time, in the right kit, ready. Coaches never forgive lateness.","xp_reward":120,"achievements":["✅ Five types of training","✅ Seven days of the week","✅ Three times of day","✅ First training schedule read in English"],"badge_unlocked":"Week Reader","next_lesson_preview":"Next: Session 2.6 — Getting Around.","translation_available":true}],"session":5,"difficulty":"A2","skill_area":"fitness"}', null, null, null, true, 11, '2026-08-14 01:33:26.734682+00', '2026-08-14 01:33:26.734682+00', null, null, null, null, 2, 5, null, null, null, 'players', false, 'propath_26_27', ARRAY['fitness']), ('9e4c5b32-0eb6-4147-a4e3-9063a9816a02', '6. Daily Life: Getting Around', null, 102, null, 100, '{"type":"multi_step","unit":2,"steps":[{"id":"step-1","type":"scenario","title":"6. Getting Around","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/scenarios/taxi.png"},{"id":"step-2","type":"vocabulary","title":"How you get there","content":"You''ve moved out of the hotel. Now you need to get to training every morning. Five words cover almost every situation.","vocabulary":[{"english":"taxi","example":"I''ll take a taxi to training.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/taxi.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/taxi.png","usage_tip":"British ''taxi'' or American ''cab''. Uber and Bolt are common in most football cities.","translation":"táxi","pronunciation":"/ˈtæksi/"},{"english":"bus","example":"The team bus leaves at 9.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/bus.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/bus.png","usage_tip":"Team travel to matches — always ''the team bus''. Local travel — ''the bus''.","translation":"ônibus","pronunciation":"/bʌs/"},{"english":"train","example":"I take the train to the ground.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/train.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/train.png","usage_tip":"Common in European cities. Say the station name — the taxi driver / conductor knows.","translation":"trem","pronunciation":"/treɪn/"},{"english":"station","example":"The station is five minutes'' walk.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/station.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/station.png","usage_tip":"Where trains stop. In big cities — ''central station'', ''main station''.","translation":"estação","pronunciation":"/ˈsteɪʃən/"},{"english":"stop","example":"Please stop at the next stop.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/stop.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/stop.png","usage_tip":"A bus ''stop'' — smaller than a station. Also the verb — ''please stop here''.","translation":"parada","pronunciation":"/stɒp/"}]},{"id":"step-3","type":"drag_drop_vocab","title":"Match the transport","content":"Drag each word onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"tr-taxi","english":"Taxi","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/taxi.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/taxi.png","translation":"Táxi"},{"id":"tr-bus","english":"Bus","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/bus.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/bus.png","translation":"Ônibus"},{"id":"tr-train","english":"Train","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/train.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/train.png","translation":"Trem"},{"id":"tr-station","english":"Station","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/station.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/station.png","translation":"Estação"},{"id":"tr-stop","english":"Stop","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/stop.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/stop.png","translation":"Parada"}],"display_mode":"image"}},{"id":"step-4","type":"vocabulary","title":"What to say to the driver","content":"Five short phrases and you''re never stuck in a taxi in London, Madrid, or Los Angeles. Every driver hears these ten times a day.","vocabulary":[{"english":"Take me to…","example":"Take me to the training ground, please.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/take-me-to.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/take-me-to.png","usage_tip":"The classic taxi instruction. Say the address slowly and clearly. Show it on your phone if you can.","translation":"Me leva ao / à…","pronunciation":"/teɪk miː tə/"},{"english":"How much?","example":"How much is it to the airport?","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/how-much.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/how-much.png","usage_tip":"Ask this BEFORE the journey when you can. Prices vary by city and time of day.","translation":"Quanto custa?","pronunciation":"/haʊ mʌtʃ/"},{"english":"How long?","example":"How long to the ground from here?","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/how-long.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/how-long.png","usage_tip":"Asks about time. Traffic depends on the city — Manchester on a Friday is not Madrid on a Sunday.","translation":"Quanto tempo?","pronunciation":"/haʊ lɒŋ/"},{"english":"Please stop here.","example":"Please stop here — this is fine.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/please-stop-here.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/please-stop-here.png","usage_tip":"Signals the driver to pull over. ''Here is fine'' works too — less formal, still polite.","translation":"Pode parar aqui, por favor.","pronunciation":"/pliːz stɒp hɪə/"},{"english":"Where is…?","example":"Excuse me — where is the station?","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/where-is.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/where-is.png","usage_tip":"Start with ''excuse me'' before asking. In English, that little politeness matters more than the question.","translation":"Onde fica…?","pronunciation":"/weər ɪz/"}]},{"id":"step-5","type":"drag_drop_vocab","title":"Match the phrase","content":"Drag each phrase onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"p-take","english":"Take me to…","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/take-me-to.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/take-me-to.png","translation":"Me leva ao…"},{"id":"p-much","english":"How much?","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/how-much.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/how-much.png","translation":"Quanto custa?"},{"id":"p-long","english":"How long?","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/how-long.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/how-long.png","translation":"Quanto tempo?"},{"id":"p-stop","english":"Please stop here.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/please-stop-here.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/please-stop-here.png","translation":"Pode parar aqui."},{"id":"p-where","english":"Where is…?","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/where-is.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/where-is.png","translation":"Onde fica…?"}],"display_mode":"image"}},{"id":"step-6","type":"ai_gap_fill","title":"In the taxi","content":"Fill in the gap.","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/scenarios/taxi.png","sentences":[{"id":"gap-1","text":"YOU: ''Take me ___ the training ground, please.''","context":"Telling the driver your destination","options":["to","in","on","at"],"hint_context":"''Take me [word] the ground''.","correct_answers":["to"]},{"id":"gap-2","text":"YOU: ''___ much is it to the airport?''","context":"Asking about the fare","options":["How","What","When","Why"],"hint_context":"The question word for quantity/price.","correct_answers":["How"]}],"xp_reward":25},{"id":"step-7","type":"ai_speech_practice","title":"Get in and give an address","prompt":"","context":"In a taxi","xp_reward":30,"expectedText":"Good morning. Take me to the training ground, please. How long from here?","instructions":{"en":"Greet the driver first. Say the address slowly. Then the practical question. Warmth costs nothing.","pt":"Cumprimente o motorista primeiro. Diga o endereço devagar. Depois a pergunta prática. A simpatia não custa nada."}},{"id":"step-8","type":"memory_match","title":"Getting-around review","xp_reward":60,"vocabulary":[{"en":"Taxi","id":1,"pt":"Táxi","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/taxi.png"},{"en":"Bus","id":2,"pt":"Ônibus","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/bus.png"},{"en":"Train","id":3,"pt":"Trem","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/train.png"},{"en":"Station","id":4,"pt":"Estação","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/station.png"},{"en":"Take me to…","id":5,"pt":"Me leva ao…","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/take-me-to.png"},{"en":"How much?","id":6,"pt":"Quanto custa?","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/how-much.png"},{"en":"Please stop here.","id":7,"pt":"Pode parar aqui.","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/please-stop-here.png"},{"en":"Where is…?","id":8,"pt":"Onde fica…?","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/where-is.png"}],"display_mode":"image"},{"id":"step-9","type":"completion","title":"Independent","content":"You can move around any football city in the world in English. Taxi to training, train to the airport, ask a stranger where the bus stop is — and understand the answer. That''s Unit 2 complete. Six skills at fifty percent on the Training Centre radar. You''re halfway to your first certificate.","xp_reward":140,"achievements":["✅ Five transport words","✅ Five taxi phrases mastered","✅ First independent journey planned","✅ Unit 2: The Signing — complete"],"badge_unlocked":"Independent","unit_completion":true,"next_lesson_preview":"Unit 3 — The Debut — opens with match-day language at real match speed.","translation_available":true}],"session":6,"difficulty":"A2","skill_area":"daily-life"}', null, null, null, true, 12, '2026-08-14 01:34:28.830843+00', '2026-08-14 01:34:28.830843+00', null, null, null, null, 2, 6, null, null, null, 'players', false, 'propath_26_27', ARRAY['daily_life']);